/**
 * Builds the web UI (web/) and embeds the result in the Worker as
 * src/ui/assets.gen.ts, so the Worker serves /ui with no asset binding.
 *
 * Runs after `bun install` and before every deploy. The generated file is
 * gitignored: rebuild it with `bun run build:ui`.
 */
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { extname, join, relative } from "node:path";

const root = join(import.meta.dirname, "..");
const web = join(root, "web");
const dist = join(web, "dist", "client");
const out = join(root, "src", "ui", "assets.gen.ts");

// web/ is its own package, not a workspace: `cf deploy` refuses to run in a
// workspace root.
for (const step of [
  ["bun", "install", "--frozen-lockfile"],
  ["bun", "run", "build"],
]) {
  const run = Bun.spawnSync(step, { cwd: web, stdout: "inherit", stderr: "inherit" });
  if (run.exitCode !== 0) throw new Error(`embed-ui: ${step.join(" ")} failed in web/`);
}

const TYPES: Record<string, string> = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".ico": "image/x-icon",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};
const TEXT = new Set([".css", ".html", ".js", ".json", ".svg", ".txt"]);

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

const files: Record<string, { type: string; body: string; base64: boolean }> = {};
for (const path of walk(dist)) {
  const ext = extname(path);
  const type = TYPES[ext];
  if (type == null) throw new Error(`embed-ui: no content type for ${path}`);
  const rel = relative(dist, path).split("\\").join("/");
  // The prerendered shell is the page itself; everything else sits under /ui/.
  const url = rel === "_shell.html" ? "/ui" : `/ui/${rel}`;
  const bytes = readFileSync(path);
  files[url] = TEXT.has(ext)
    ? { type, body: bytes.toString("utf8"), base64: false }
    : { type, body: bytes.toString("base64"), base64: true };
}

const shell = files["/ui"];
if (shell == null) throw new Error("embed-ui: the build has no _shell.html");

// The shell's inline scripts (router bootstrap, theme) run under a CSP that
// names each one by hash, so no other inline script can.
const hashes = [...shell.body.matchAll(/<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/gu)]
  .map((m) => m[1]!)
  .filter((body) => body.length > 0)
  .map((body) => `'sha256-${createHash("sha256").update(body).digest("base64")}'`);

writeFileSync(
  out,
  `// Generated by scripts/embed-ui.ts from web/. Do not edit.\n` +
    `export const UI_FILES: Record<string, { type: string; body: string; base64: boolean }> = ${JSON.stringify(files)};\n` +
    `export const UI_SCRIPT_HASHES: string[] = ${JSON.stringify(hashes)};\n`,
);
console.log(`embed-ui: ${Object.keys(files).length} files, ${hashes.length} inline scripts -> ${relative(root, out)}`);
